function queryNetList(){var t=getUrlParameter("fundId");getUrlParameter("isSub");$.ajax({async:!0,url:"/WeixinService/business/queryEstimateByFundId.xhtml",data:{fundId:t},dataType:"json",type:"POST",cache:!1,error:function(t,a){show_tips("网络繁忙，请稍后再试。")},success:function(t){var a=t.productEstimateList,e="";if(null!=a&&0<a.length){var n="";$.each(a,function(t,a){n=0<=a.fluctuate?"<span class='red'>"+parseFloat(numMulti(a.fluctuate,100)).toFixed(2)+"%</span>":"<span class='green'>"+parseFloat(numMulti(a.fluctuate,100)).toFixed(2)+"%</span>",e+="<li>",e+="<span>"+formatDate(a.eDate)+"</span>",e+="<span>"+parseFloat(a.netValue).toFixed(4)+"</span>",e+="<span>"+parseFloat(a.accNetValue).toFixed(4)+"</span>",e+=n,e+="</li>"}),$(".historyNetworthCon ul").html(e)}}})}$(document).ready(function(t){queryNetList()});